SELECT current_database(),current_setting('transaction_read_only'),now();
SELECT c.relname AS table_name, con.conname AS constraint_name, pg_get_constraintdef(con.oid) AS definition FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND con.contype='c' AND (c.relname ~ '(config|policy|protocol|inventory|ration|stage|status|identifier|sales|feed|health|milk|vaccination|proof|workforce)') ORDER BY c.relname,con.conname;
SELECT table_name,column_name,column_default FROM information_schema.columns WHERE table_schema='public' AND column_default IS NOT NULL AND table_name ~ '(config|policy|protocol|inventory|ration|stage|status|identifier|sales|feed|health|milk|vaccination|proof|workforce)' AND column_name !~ '(^.*_id$|created_at|updated_at|row_version)' ORDER BY table_name,ordinal_position;
